{
  "name": "dsh-sidebar-balance",
  "version": "0.1.1",
  "description": "Minimalist, native-adaptive DeepSeek Harness balance widget: DeepSeek official account balance + OpenCode Go plan consumption ring in the sidebar footer, frosted-glass hover card, in-UI restart. · 极简原生风 DSH 余额插件:侧边栏常驻 DeepSeek 余额与 Go 套餐消耗圆环,磨砂悬浮卡,一键重启",
  "type": "module",
  "main": "lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./client": "./lib/client.js",
    "./package.json": "./package.json"
  },
  "files": [
    "lib",
    "cordis.patch.yml",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "dsh",
    "deepseek-harness",
    "dsh-plugin",
    "deepseek",
    "opencode",
    "opencode-go",
    "balance",
    "quota",
    "minimal",
    "plugin",
    "cordis"
  ],
  "engines": {
    "node": ">=18"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zhouchengke2046/dsh-sidebar-balance.git"
  },
  "homepage": "https://github.com/zhouchengke2046/dsh-sidebar-balance#readme",
  "dsh": {
    "bundle": {
      "patch": "./cordis.patch.yml"
    },
    "client": {
      "platform": "web",
      "inject": [
        "@deepseek-ai/dsh-client-runtime"
      ]
    }
  }
}
